const CACHE='packflow-live-v015-date-admin';const ASSETS=['/','/index.html','/app.js','/core.js','/store.js','/style.css','/config.js','/imports.js','/ui-tools.js','/login-tools.js','/admin-tools.js','/people-import.js','/mobile-tools.js','/packing-math.js','/record-tools.js','/outstanding.js','/admin-menu.js','/date-range.js','/portal.js','/mobile.html','/mobile.webmanifest','/spark.js','/admin.html','/admin.webmanifest','/icon.svg'];
self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(ASSETS)).then(()=>self.skipWaiting())));
self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(a=>Promise.all(a.filter(k=>k.startsWith('packflow-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',e=>{const u=new URL(e.request.url);if(e.request.method!=='GET'||u.origin!==location.origin)return;e.respondWith(fetch(e.request).then(r=>{if(r.ok&&ASSETS.includes(u.pathname)){const copy=r.clone();caches.open(CACHE).then(c=>c.put(e.request,copy));}return r;}).catch(()=>caches.match(e.request).then(r=>r||(e.request.mode==='navigate'?caches.match('/index.html'):Response.error()))));});
